insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-1719', '["phrase"]'::jsonb, '{"advanced-native-1719-v1-audio":{"type":"mc","answers":["多項過程資料合起來，讓準備工作清楚顯現。"],"options":["完成演出已展示每項準備細節，後來資料沒有新作用。","團隊只列出預計要做的事，沒有留下已做資料。","材料只記錄演出怎樣宣傳，沒有展示團隊試過的取捨。","多項過程資料合起來，讓準備工作清楚顯現。"]},"advanced-native-1719-v2-reply":{"type":"mc","answers":["We could see the stages together rather than only the polished result.","The combined record made the team’s process much clearer.","They let the amount of preparation come fully into view.","The material showed choices that the finished performance did not reveal."],"options":["We could see the stages together rather than only the polished result.","The combined record made the team’s process much clearer.","They let the amount of preparation come fully into view.","The material showed choices that the finished performance did not reveal."]},"advanced-native-1719-v1-scene":{"type":"mc","answers":["The communication problem comes fully into view through the letters."],"options":["The communication problem comes fully into view through the letters.","The letters add no information about why the meetings were missed.","The letters establish deliberate rejection of the meetings, rather than a failure to deliver messages."]},"advanced-native-1719-v1-contrast":{"type":"mc","answers":["只欣賞成品外觀，未見任何早期嘗試或過程資料。"],"options":["只欣賞成品外觀，未見任何早期嘗試或過程資料。","把分散的記錄合起來，看出取捨怎樣發展。","比較草稿、筆記及版本，清楚看見準備過程。"]},"advanced-native-1719-v1-branch":{"type":"mc","answers":["The preparation came fully into view through the drafts and notes, not through the polished performance alone."],"options":["Leave the earlier versions out because only the final result can tell us how the decisions developed.","Treat the programme’s list of names as a complete account of every choice the team tested.","The preparation came fully into view through the drafts and notes, not through the polished performance alone."]},"advanced-native-1719-v1-final":{"type":"open","answers":["The travel difficulties will only come fully into view if we also hear from residents farther from the hall. Could we keep the consultation open before choosing the meeting place?","We need the wider travel pattern to come fully into view, not just the experience of people living nearby. I would ask the other residents about their routes before settling the arrangement."],"options":[]}}'::jsonb),
('advanced-native-1720', '["phrase"]'::jsonb, '{"advanced-native-1720-v1-audio":{"type":"mc","answers":["成員共同回應外界責怪，仍願檢視實際問題。"],"options":["共同回應是批評出現前已排的例行宣布，而非對批評作反應。","成員共同回應外界責怪，仍願檢視實際問題。","成員互相公開指責，沒有共同回應。","隊伍已拒絕看任何延誤紀錄或回答問題。"]},"advanced-native-1720-v2-reply":{"type":"mc","answers":["They closed ranks to explain the record while agreeing to review the delay.","They made a shared response rather than blame one another publicly.","They defended the team without saying the delivery problem should be ignored.","The members stood together and still left room for a practical review."],"options":["They closed ranks to explain the record while agreeing to review the delay.","They made a shared response rather than blame one another publicly.","They defended the team without saying the delivery problem should be ignored.","The members stood together and still left room for a practical review."]},"advanced-native-1720-v1-scene":{"type":"mc","answers":["The committee closed ranks in response to the misleading account, while inviting questions."],"options":["The members split into separate public accusations rather than give a shared account.","The invitation to ask questions means they have refused to make any defence of the members.","The committee closed ranks in response to the misleading account, while inviting questions."]},"advanced-native-1720-v1-contrast":{"type":"mc","answers":["團結一方在實質問題上必然正確。"],"options":["群體面對挑戰時團結起來。","團結一方在實質問題上必然正確。","上下文可顯示是合理支持還是拒絕檢視。"]},"advanced-native-1720-v1-branch":{"type":"mc","answers":["We can close ranks against unfair blame and still examine the actual delay."],"options":["Use the shared defence as a reason to leave the delivery records unread.","Avoid a common response until every member has exactly the same view of the cause.","We can close ranks against unfair blame and still examine the actual delay."]},"advanced-native-1720-v1-final":{"type":"open","answers":["The family closed ranks against the rumour, but then extended that defence to shutting out the child’s reasonable question. I would distinguish their wish to protect one another from their refusal to listen.","They close ranks when the outside story threatens a family member, which explains the shared response. It does not by itself justify ignoring the child’s separate concern."],"options":[]}}'::jsonb),
('advanced-native-1721', '["phrase"]'::jsonb, '{"advanced-native-1721-v1-audio":{"type":"mc","answers":["出現場地問題，小組先弄清並核替代。"],"options":["原房間仍可用，小組沒有遇到任何改動。","所有成員已在原房間開完會，之後才知改地點。","出現場地問題，小組先弄清並核替代。","小組先傳另一地址給成員，之後才查那地方是否可用。"]},"advanced-native-1721-v2-reply":{"type":"mc","answers":["We checked an alternative before telling members where to meet.","The immediate problem led us to clarify the new arrangement.","We responded to the lost room rather than send people to an unchecked location.","When trouble knocks, we check what changed; that time we looked for another place before giving directions."],"options":["We checked an alternative before telling members where to meet.","The immediate problem led us to clarify the new arrangement.","We responded to the lost room rather than send people to an unchecked location.","When trouble knocks, we check what changed; that time we looked for another place before giving directions."]},"advanced-native-1721-v1-scene":{"type":"mc","answers":["When trouble knocks, the friends begin by finding out what help is actually needed."],"options":["The friends are revising a disputed paragraph while the printer continues to work normally.","When trouble knocks, the friends begin by finding out what help is actually needed.","The problem is described as solved before anyone asks which pages are needed."]},"advanced-native-1721-v1-contrast":{"type":"mc","answers":["困難本身已證人物故意做錯事。"],"options":["上下文仍需說清是哪項問題。","在困難出現或影響事情的時候。","困難本身已證人物故意做錯事。"]},"advanced-native-1721-v1-branch":{"type":"mc","answers":["When trouble knocks, a clear first step matters; let us confirm the place before sending everyone there."],"options":["Send members to the original room because changing a message would be inconvenient.","When trouble knocks, a clear first step matters; let us confirm the place before sending everyone there.","Choose the most familiar address and announce it before asking whether it is open."]},"advanced-native-1721-v1-final":{"type":"open","answers":["When trouble knocks, it helps to have someone who asks what is actually needed. Thank you for checking which bag I needed most and bringing it to the place we agreed last week.","I appreciated your calm help when trouble knocked last week and my plans suddenly changed. You asked before acting, and getting that bag back made the next step easier."],"options":[]}}'::jsonb),
('advanced-native-1722', '["phrase"]'::jsonb, '{"advanced-native-1722-v1-audio":{"type":"mc","answers":["沒有張揚的實際改動，仍幫人找到正確地方。"],"options":["鄰居沒有改任何資訊，只舉行公開慶祝。","新便條只有寫字的人能理解，其他人仍找不到地方。","幫忙已在大型宣傳中逐項介紹給全場。","沒有張揚的實際改動，仍幫人找到正確地方。"]},"advanced-native-1722-v2-reply":{"type":"mc","answers":["People could follow the new note the next morning.","Its value lay in the practical effect, not in an announcement about the helper.","It did not make a big noise, but it helped people find the right place.","The neighbour made the instructions usable without turning it into a public event."],"options":["People could follow the new note the next morning.","Its value lay in the practical effect, not in an announcement about the helper.","It did not make a big noise, but it helped people find the right place.","The neighbour made the instructions usable without turning it into a public event."]},"advanced-native-1722-v1-scene":{"type":"mc","answers":["The care does not make a big noise, but the absent member can use the notes to take part."],"options":["The notes are mainly an announcement praising the writer, rather than a record the absent member can use.","The notes leave out the open questions, so the absent member is told there is nothing left to contribute.","The care does not make a big noise, but the absent member can use the notes to take part."]},"advanced-native-1722-v1-contrast":{"type":"mc","answers":["行動沒有實際作用，沒有人可能從中受益。"],"options":["行動沒有實際作用，沒有人可能從中受益。","需由實際回應看低調行動帶來甚麼幫助。","沒有刻意張揚或很多宣傳。"]},"advanced-native-1722-v1-branch":{"type":"mc","answers":["It did not make a big noise, but the practical help is still worth describing."],"options":["Include only the large announcements when deciding what helped people.","Measure the note only by how often the helper’s name was repeated.","It did not make a big noise, but the practical help is still worth describing."]},"advanced-native-1722-v1-final":{"type":"open","answers":["His help does not make a big noise, but first-time visitors can find their way and ask for readable information because of it. I would recognise those quiet, repeated contributions in the service award.","The care does not make a big noise; he checks routes and information needs without making himself the centre of the visit. Those practical details are why I am nominating him."],"options":[]}}'::jsonb),
('advanced-native-1723', '["phrase"]'::jsonb, '{"advanced-native-1723-v1-audio":{"type":"mc","answers":["安排需顧其他人的限制，不只一人交通。"],"options":["安排需顧其他人的限制，不只一人交通。","別人的需要表示他不再可以提自己的火車時間。","小組已選擇只按他的時間，不計其他人。","各人的限制其實相同，沒有任何不同需要。"]},"advanced-native-1723-v2-reply":{"type":"mc","answers":["Everyone needed a chance to explain what they could manage.","The world did not revolve around him; other people’s duties and work hours mattered too.","His train was not the only constraint on the group’s time.","The plan had to include needs he had not yet considered."],"options":["Everyone needed a chance to explain what they could manage.","The world did not revolve around him; other people’s duties and work hours mattered too.","His train was not the only constraint on the group’s time.","The plan had to include needs he had not yet considered."]},"advanced-native-1723-v1-scene":{"type":"mc","answers":["She needs to remember that the world does not revolve around her when they plan the day."],"options":["She needs to remember that the world does not revolve around her when they plan the day.","Asking the others means she must never mention her own interests again.","Only the person who first suggested the trip should have a view on the route."]},"advanced-native-1723-v1-contrast":{"type":"mc","answers":["他們自己的需要完全沒有價值。"],"options":["別人的需要也要被考慮。","他們自己的需要完全沒有價值。","可用具體共同安排解釋為何不能只顧一人。"]},"advanced-native-1723-v1-branch":{"type":"mc","answers":["The world does not revolve around you, but your needs still belong in a discussion that includes everyone else’s."],"options":["The world does not revolve around you, but your needs still belong in a discussion that includes everyone else’s.","Leave your travel needs out so the others can make a plan without that information.","Give your train priority before asking whether the others have caring duties."]},"advanced-native-1723-v1-final":{"type":"open","answers":["I need to remember that the world does not revolve around me; I cut your ending before asking why it mattered to you. I am sorry, and I would like us to discuss what each of us wants to keep.","The world does not revolve around me, and my preferred ending should not have been the only one considered. Could you explain what you want the final scene to do before we revise it together?"],"options":[]}}'::jsonb),
('advanced-native-1724', '["phrase"]'::jsonb, '{"advanced-native-1724-v1-audio":{"type":"mc","answers":["注意由自己展示擴到訪客的實際需要。"],"options":["主要目的是比較誰的展示得到最多掌聲。","注意由自己展示擴到訪客的實際需要。","大家不再可關心自己的作品或準備。","訪客已全問完問題，沒有任何需留意的情況。"]},"advanced-native-1724-v2-reply":{"type":"mc","answers":["It helped us look up, look around, and step outside ourselves to notice visitors who needed a place to ask.","We began considering more than our own display.","The visitors’ experience became part of what we watched for.","We noticed a practical need we had missed while focusing on our own work."],"options":["It helped us look up, look around, and step outside ourselves to notice visitors who needed a place to ask.","We began considering more than our own display.","The visitors’ experience became part of what we watched for.","We noticed a practical need we had missed while focusing on our own work."]},"advanced-native-1724-v1-scene":{"type":"mc","answers":["We need to look up, look around, and step outside ourselves when planning for the newcomers."],"options":["Listening to newcomers means the organisers cannot mention their own experience at all.","We need to look up, look around, and step outside ourselves when planning for the newcomers.","Only the organisers’ favourite activities should guide what newcomers are offered."]},"advanced-native-1724-v1-contrast":{"type":"mc","answers":["必須否定及忽略自己所有需要。"],"options":["擴闊注意及觀點，留意別人。","必須否定及忽略自己所有需要。","需交代因看見別人而有甚麼具體理解或改動。"]},"advanced-native-1724-v1-branch":{"type":"mc","answers":["We can look up, look around, and step outside ourselves without pretending our own needs do not exist."],"options":["Keep the visitors’ difficulties out of the planning so the display remains our only concern.","Remove all the organisers’ practical questions instead of hearing both sets of needs.","We can look up, look around, and step outside ourselves without pretending our own needs do not exist."]},"advanced-native-1724-v1-final":{"type":"open","answers":["We should look up, look around, and step outside ourselves before deciding how the shared space will be used. Could we hear from families, older residents and night workers as well as bring our own ideas?","Let us look up, look around, and step outside ourselves by asking different residents about their actual use of the space. We can put our proposal beside those needs rather than assume it suits everyone."],"options":[]}}'::jsonb),
('advanced-native-1725', '["phrase"]'::jsonb, '{"advanced-native-1725-v1-audio":{"type":"mc","answers":["早前受歡迎的經驗，持續影響他後來如何接待新人。"],"options":["他後來的做法與早前經驗完全無關，敘述沒作連接。","說話者只在對比兩位鄰居的社交風格，沒有描述一個人的長久影響。","早前受歡迎的經驗，持續影響他後來如何接待新人。","陰影表示那鄰居的行為在敘述中主要帶來恐懼。"]},"advanced-native-1725-v2-reply":{"type":"mc","answers":["He remembered the patient introduction and repeated the care for others.","The welcome became a model he returned to in later situations.","A small early kindness influenced his later habit of including people.","It left a long shadow in a good way, shaping how he welcomed newcomers years later."],"options":["He remembered the patient introduction and repeated the care for others.","The welcome became a model he returned to in later situations.","A small early kindness influenced his later habit of including people.","It left a long shadow in a good way, shaping how he welcomed newcomers years later."]},"advanced-native-1725-v1-scene":{"type":"mc","answers":["Her example left a long shadow in a good way."],"options":["Her example left a long shadow in a good way.","The account says the apprentices forgot her approach as soon as she left.","The influence is presented mainly as a burden that prevented anyone from learning."]},"advanced-native-1725-v1-contrast":{"type":"mc","answers":["long shadow 在任何語境都只代表值得稱讚。"],"options":["需有具體後續，才知好影響如何延續。","明說有長久正面影響。","long shadow 在任何語境都只代表值得稱讚。"]},"advanced-native-1725-v1-branch":{"type":"mc","answers":["The writer adds “in a good way” and shows the welcome shaping later care, so the shadow is deliberately positive here."],"options":["Treat the word shadow alone as proof that every later choice was controlled by the neighbour.","The writer adds “in a good way” and shows the welcome shaping later care, so the shadow is deliberately positive here.","Ignore the qualifier and describe the later care as fear of the neighbour."]},"advanced-native-1725-v1-final":{"type":"open","answers":["The open music archive has left a long shadow in a good way: later composers used the local melodies to create work in their own styles. Its influence lives on through adaptation, not only imitation.","Sharing the old scores left a long shadow in a good way, giving new writers material they could reshape. This display follows that continuing influence without treating the original version as the only possible model."],"options":[]}}'::jsonb),
('advanced-native-1727', '["phrase"]'::jsonb, '{"advanced-native-1727-v1-audio":{"type":"mc","answers":["耐心對待學習失手，不代表容忍嘲笑別人。"],"options":["耐心對待學習失手，不代表容忍嘲笑別人。","教練把任何不明白的提問都當壞行為。","教練沒有回應嘲笑，只叫初學者別再問。","球員只是在有禮提出不同訓練偏好，沒有嘲笑。"]},"advanced-native-1727-v2-reply":{"type":"mc","answers":["She wanted to protect respectful participation while still allowing people to learn.","She was not putting up with bad behaviour towards the beginner.","The players were mocking questions instead of responding respectfully.","Patience with mistakes did not mean accepting ridicule."],"options":["She wanted to protect respectful participation while still allowing people to learn.","She was not putting up with bad behaviour towards the beginner.","The players were mocking questions instead of responding respectfully.","Patience with mistakes did not mean accepting ridicule."]},"advanced-native-1727-v1-scene":{"type":"mc","answers":["The leader is not putting up with bad behaviour, while making room for respectful disagreement."],"options":["The interruptions are continuing without any response from the leader.","The leader is not putting up with bad behaviour, while making room for respectful disagreement.","The leader is treating every different opinion as an insult."]},"advanced-native-1727-v1-contrast":{"type":"mc","answers":["同伴有禮提出不同建議，大家聽理由再討論。"],"options":["同伴有禮提出不同建議，大家聽理由再討論。","有人反覆侮辱發言者，旁人把它當可接受而不回應。","有人嘲笑新人，負責人聽到仍任其繼續。"]},"advanced-native-1727-v1-branch":{"type":"mc","answers":["Patience does not require putting up with bad behaviour; she can stop the ridicule without humiliating anyone."],"options":["Patience does not require putting up with bad behaviour; she can stop the ridicule without humiliating anyone.","Ask the beginner to remain silent so the others do not have to change how they respond.","Describe the mockery as ordinary disagreement without checking how the questions were treated."]},"advanced-native-1727-v1-final":{"type":"open","answers":["I do not want us to confuse listening to disagreement with putting up with bad behaviour. Could we agree rules that allow different views but stop personal insults before the next writing meeting?","I would be glad to join a discussion that welcomes different ideas without putting up with bad behaviour towards the speakers. Let us make that distinction clear in the meeting rules."],"options":[]}}'::jsonb),
('advanced-native-1728', '["phrase"]'::jsonb, '{"advanced-native-1728-v1-audio":{"type":"mc","answers":["她先親自示範怎回應失手及求回饋，再邀別人跟。"],"options":["年輕樂手先示範求回饋，她之後才跟着嘗試。","她先親自示範怎回應失手及求回饋，再邀別人跟。","她只批評年輕樂手，沒有提自己的失手。","她私下改好自己的失手，沒有向其他人展示求回饋。"]},"advanced-native-1728-v2-reply":{"type":"mc","answers":["She led by example, first naming her own practice need and asking for feedback.","She showed the response herself before inviting them to try it.","Her own mistake became a chance to model learning rather than hide it.","She made the request for feedback something the leader did too."],"options":["She led by example, first naming her own practice need and asking for feedback.","She showed the response herself before inviting them to try it.","Her own mistake became a chance to model learning rather than hide it.","She made the request for feedback something the leader did too."]},"advanced-native-1728-v1-scene":{"type":"mc","answers":["She is leading by example by returning her own tools as she asks others to do."],"options":["She is leading by example by returning her own tools as she asks others to do.","She has left all her own tools out while telling others to tidy theirs.","She has assigned the packing to a separate team and left without demonstrating it herself."]},"advanced-native-1728-v1-contrast":{"type":"mc","answers":["只發出要求，自己的相同行為卻與要求相反。"],"options":["自己實際採取希望別人學的行動。","只發出要求，自己的相同行為卻與要求相反。","先示範回應方法，再邀同伴嘗試。"]},"advanced-native-1728-v1-branch":{"type":"mc","answers":["She can lead by example through showing how to learn from a mistake, not only through flawless playing."],"options":["Ask the younger players to accept criticism while the leader refuses comments on her own work.","She can lead by example through showing how to learn from a mistake, not only through flawless playing.","Keep the feedback request private and show the younger players only the finished version."]},"advanced-native-1728-v1-final":{"type":"open","answers":["She leads by example by naming other people’s contributions whenever she presents the work. The rest of the group has begun doing the same, which is why I would nominate her as coordinator.","I would nominate her because she has led by example in giving clear credit, not merely asked the others to do it. Her habit has encouraged more careful acknowledgement across the group."],"options":[]}}'::jsonb),
('advanced-native-1729', '["phrase"]'::jsonb, '{"advanced-native-1729-v1-audio":{"type":"mc","answers":["孩子先見耐心行為，後來嘗試相似關懷。"],"options":["叔叔每次打斷訪客，孩子照樣學打斷。","孩子只記得叔叔說過耐心的定義，沒有在待人時嘗試。","孩子先見耐心行為，後來嘗試相似關懷。","孩子只在聽完正式規則課後才首次看見那行為。"]},"advanced-native-1729-v2-reply":{"type":"mc","answers":["She repeated the patience she had seen rather than interrupting the visitor.","Her later response resembled the uncle’s small act of care.","The account links an observed example with her own attempt.","Kindness is often caught before it is taught; she later gave another visitor time to speak."],"options":["She repeated the patience she had seen rather than interrupting the visitor.","Her later response resembled the uncle’s small act of care.","The account links an observed example with her own attempt.","Kindness is often caught before it is taught; she later gave another visitor time to speak."]},"advanced-native-1729-v1-scene":{"type":"mc","answers":["The rule is remembered, but we do not yet have an example showing that kindness was caught before it was taught."],"options":["Reciting the rule establishes that he first learned the behaviour by watching someone.","The evidence already describes how patiently he welcomed a visitor after watching an adult.","The rule is remembered, but we do not yet have an example showing that kindness was caught before it was taught."]},"advanced-native-1729-v1-contrast":{"type":"mc","answers":["看到一次榜樣，就可跳過後來討論怎在不同情況實行。"],"options":["需有具體看到及嘗試的線索，不能只用口號。","觀察榜樣可先於明確教導影響關懷行為。","看到一次榜樣，就可跳過後來討論怎在不同情況實行。"]},"advanced-native-1729-v1-branch":{"type":"mc","answers":["Kindness is often caught before it is taught; the observed example can matter even before a formal lesson."],"options":["Ignore the imitation unless the child can first recite a rule about patience.","Ask her to repeat a definition before discussing the way she actually welcomed the visitor.","Kindness is often caught before it is taught; the observed example can matter even before a formal lesson."]},"advanced-native-1729-v1-final":{"type":"open","answers":["Kindness is often caught before it is taught, and I learned from the way you listened when someone made a mistake. I now try to ask what happened before judging a colleague, so thank you for that example.","I think kindness is often caught before it is taught because I remember your patient questions more than any speech. I am still learning, but I try to bring that approach into my own work with others."],"options":[]}}'::jsonb),
('advanced-native-1730', '["phrase"]'::jsonb, '{"advanced-native-1730-v1-audio":{"type":"mc","answers":["不喜歡回顧形式帶來的責任感，仍可喜歡書本。"],"options":["回顧仍完全自願，沒有表格或要求改變。","說話者只在報告評論已寫完，沒表達態度。","不喜歡回顧形式帶來的責任感，仍可喜歡書本。","說話者是對書的內容失去興趣，而不是對回顧形式有負擔。"]},"advanced-native-1730-v2-reply":{"type":"mc","answers":["The format felt like a duty rather than a chance to share a discovery.","I still liked the books, but did not enjoy repeating the same answers in the form.","The change in the review process affected how I felt about doing it.","I began to see it as a chore when it became a compulsory repetitive form."],"options":["The format felt like a duty rather than a chance to share a discovery.","I still liked the books, but did not enjoy repeating the same answers in the form.","The change in the review process affected how I felt about doing it.","I began to see it as a chore when it became a compulsory repetitive form."]},"advanced-native-1730-v1-scene":{"type":"mc","answers":["The photo task matters to her, but she has begun to see it as a chore."],"options":["The account says she has stopped caring about the club altogether.","Her attitude is not discussed; the passage only counts completed photographs.","The photo task matters to her, but she has begun to see it as a chore."]},"advanced-native-1730-v1-contrast":{"type":"mc","answers":["改善那活動的形式也不會影響當事人的態度。"],"options":["需要活動先行詞，才知道 it 指甚麼。","當事人把那活動看成不太想做的責任。","改善那活動的形式也不會影響當事人的態度。"]},"advanced-native-1730-v1-branch":{"type":"mc","answers":["I see it as a chore because of the form, not because I have lost interest in the books."],"options":["I see it as a chore because of the form, not because I have lost interest in the books.","Recommend different books without asking what makes the review form repetitive.","Keep adding the same questions before asking whether they help anyone share discoveries."]},"advanced-native-1730-v1-final":{"type":"open","answers":["The rhythm practice used to feel pointless, and I would see it as a chore